  dict(q="Meaning asks whether you:", o=["Understand the business and it aligns with your values", "Like the stock price", "Know the CEO personally"], a=0, why="Invest in what you understand."),
  dict(q="A moat is:", o=["A lasting competitive advantage", "A type of bond", "A dividend"], a=0, why="It protects profits."),
  dict(q="A network effect means:", o=["A product becomes more valuable as more people use it", "Many employees", "High debt"], a=0, why="It is one kind of moat."),
  dict(q="High switching costs mean:", o=["Customers find it hard to change providers", "Prices are low", "No competition"], a=0, why="That can protect profits."),
  dict(q="To judge management, you can:", o=["Compare leaders' words with their actions", "Read only advertisements", "Ignore pay"], a=0, why="Consistency reveals character."),
  dict(q="Margin of safety means buying:", o=["Meaningfully below estimated value", "At any price", "After the price doubles"], a=0, why="It protects you if you are wrong."),
  dict(q="Moats can:", o=["Erode as technology changes", "Never change", "Guarantee returns"], a=0, why="Review them yearly."),
  dict(q="A popular product alone is:", o=["Not necessarily a lasting moat", "Always a moat", "A margin of safety"], a=0, why="Popularity can fade."),
